<template>
  <div>
  <el-dialog v-model="visible" :title="`房屋收费台账 - ${room?.roomNo || room?.roomCode || ''}`" width="1200px" append-to-body @closed="reset">
    <el-row :gutter="12" class="mb-3"><el-col v-for="card in cards" :key="card.label" :span="6"><el-card shadow="never"><div class="ledger-label">{{ card.label }}</div><div class="ledger-value">¥ {{ money(card.value) }}</div></el-card></el-col></el-row>
    <div class="mb-3"><el-button v-if="canCollect" type="primary" @click="paymentDialog?.open(room)">登记收款</el-button><el-button v-hasPermi="['property:chargeBinding:list']" @click="emit('openBinding', room!)">收费设置</el-button></div>
    <el-tabs>
      <el-tab-pane label="应收台账"><el-table v-loading="loading" :data="receivables" border max-height="430"><el-table-column label="收费项目" prop="chargeItemNameSnapshot" min-width="130" /><el-table-column label="账期" min-width="190"><template #default="s">{{ s.row.periodStartDate }} ~ {{ s.row.periodEndDate }}</template></el-table-column><el-table-column label="责任主体" prop="responsibleCustomerNameSnapshot" min-width="100" /><el-table-column label="应收" align="right"><template #default="s">{{ money(s.row.receivableAmount) }}</template></el-table-column><el-table-column label="已收" align="right"><template #default="s">{{ money(s.row.paidAmount) }}</template></el-table-column><el-table-column label="未收" align="right"><template #default="s">{{ money(s.row.outstandingAmount) }}</template></el-table-column><el-table-column label="支付状态"><template #default="s"><dict-tag :options="pm_payment_status" :value="s.row.paymentStatus" /></template></el-table-column><el-table-column label="应缴日期" prop="dueDate" width="115" /><el-table-column label="逾期" width="80"><template #default="s"><el-tag :type="s.row.overdue ? 'danger' : 'success'">{{ s.row.overdue ? '逾期' : '未逾期' }}</el-tag></template></el-table-column></el-table></el-tab-pane>
      <el-tab-pane label="收款记录"><el-table v-loading="loading" :data="payments" border max-height="430"><el-table-column label="收款编号" min-width="190"><template #default="s"><el-button link type="primary" @click="openPayment(s.row)">{{ s.row.paymentNo }}</el-button></template></el-table-column><el-table-column label="付款人" prop="payerNameSnapshot" /><el-table-column label="收款时间" prop="paymentTime" min-width="170" /><el-table-column label="收款方式"><template #default="s"><dict-tag :options="pm_payment_method" :value="s.row.paymentMethod" /></template></el-table-column><el-table-column label="金额" align="right"><template #default="s">{{ money(s.row.paymentAmount) }}</template></el-table-column><el-table-column label="状态"><template #default="s"><dict-tag :options="pm_payment_record_status" :value="s.row.status" /></template></el-table-column><el-table-column label="操作" width="80"><template #default="s"><el-button v-if="s.row.status === 'VALID'" v-hasPermi="['property:payment:reverse']" link type="danger" @click="openReverse(s.row)">冲销</el-button></template></el-table-column></el-table></el-tab-pane>
    </el-tabs>
  </el-dialog>
  <PaymentDialog ref="paymentDialog" :project-id="projectId" :project-name="projectName" @success="refresh" />
  <PaymentReverseDialog ref="reverseDialog" :project-id="projectId" @success="handleReverseSuccess" />
  <el-dialog v-model="detailVisible" title="核销详情" width="860px" append-to-body><el-descriptions v-if="detail" :column="3" border class="mb-3"><el-descriptions-item label="收款编号">{{ detail.paymentNo }}</el-descriptions-item><el-descriptions-item label="付款人">{{ detail.payerNameSnapshot }}</el-descriptions-item><el-descriptions-item label="金额">¥ {{ money(detail.paymentAmount) }}</el-descriptions-item><el-descriptions-item label="状态"><dict-tag :options="pm_payment_record_status" :value="detail.status" /></el-descriptions-item></el-descriptions><el-descriptions v-if="detail?.reversal" :column="2" border class="mb-3"><el-descriptions-item label="冲销单号">{{ detail.reversal.reversalNo }}</el-descriptions-item><el-descriptions-item label="冲销时间">{{ detail.reversal.reversalTime }}</el-descriptions-item><el-descriptions-item label="冲销金额">¥ {{ money(detail.reversal.reversalAmount) }}</el-descriptions-item><el-descriptions-item label="操作人">{{ detail.reversal.createByName || '-' }}</el-descriptions-item><el-descriptions-item label="冲销原因" :span="2">{{ detail.reversal.reason }}</el-descriptions-item></el-descriptions><el-alert v-if="detail?.status === 'REVERSED'" title="以下核销明细已随收款冲销失效，仅作为历史记录保留。" type="warning" :closable="false" show-icon class="mb-3" /><el-table :data="detail?.allocations || []" border><el-table-column label="应收编号" prop="receivableNo" min-width="180" /><el-table-column label="收费项目" prop="chargeItemNameSnapshot" /><el-table-column label="责任人" prop="responsibleCustomerNameSnapshot" /><el-table-column label="账期" min-width="190"><template #default="s">{{ s.row.periodStart }} ~ {{ s.row.periodEnd }}</template></el-table-column><el-table-column label="本次核销" align="right"><template #default="s">{{ money(s.row.allocationAmount) }}</template></el-table-column><el-table-column label="状态"><template #default="s"><dict-tag :options="pm_payment_status" :value="s.row.paymentStatus" /></template></el-table-column></el-table><template #footer><el-button v-if="detail?.status === 'VALID'" v-hasPermi="['property:payment:reverse']" type="danger" @click="reverseDialog?.open(detail)">冲销</el-button><el-button @click="detailVisible = false">关闭</el-button></template></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { getPayment, listPayment } from '@/api/property/charge/payment';
import type { PaymentVO } from '@/api/property/charge/payment/types';
import { getReceivableSummary, listReceivable } from '@/api/property/charge/receivable';
import type { ReceivableSummaryVO, ReceivableVO } from '@/api/property/charge/receivable/types';
import type { RoomVO } from '@/api/property/resource/room/types';
import { useDict } from '@/utils/dict';
import PaymentDialog from './PaymentDialog.vue';
import PaymentReverseDialog from './PaymentReverseDialog.vue';

const props = defineProps<{ projectId?: number | string; projectName: string }>();
const emit = defineEmits<{ openBinding: [room: RoomVO] }>();
const { pm_payment_method, pm_payment_record_status, pm_payment_status } = toRefs<any>(useDict('pm_payment_method', 'pm_payment_record_status', 'pm_payment_status'));
const visible = ref(false), loading = ref(false), detailVisible = ref(false), room = ref<RoomVO>(), receivables = ref<ReceivableVO[]>([]), payments = ref<PaymentVO[]>([]), detail = ref<PaymentVO>(), paymentDialog = ref<InstanceType<typeof PaymentDialog>>(), reverseDialog = ref<InstanceType<typeof PaymentReverseDialog>>();
const summary = ref<ReceivableSummaryVO>({ receivableTotal: 0, paidTotal: 0, outstandingTotal: 0, overdueOutstandingTotal: 0 });
const canCollect = computed(() => false), cards = computed(() => [{ label: '累计应收', value: summary.value.receivableTotal }, { label: '累计已收', value: summary.value.paidTotal }, { label: '当前未收', value: summary.value.outstandingTotal }, { label: '逾期未收', value: summary.value.overdueOutstandingTotal }]); let version = 0;
const money = (v?: number) => Number(v || 0).toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
async function refresh() { const p = props.projectId, roomId = room.value?.id, v = ++version; if (!p || !roomId) return; loading.value = true; try { const [sum, bills, receipts] = await Promise.all([getReceivableSummary({ projectId: p, roomId, pageNum: 1, pageSize: 1 }), listReceivable({ projectId: p, roomId, pageNum: 1, pageSize: 1000 }), listPayment({ projectId: p, roomId, pageNum: 1, pageSize: 1000 })]); if (v !== version || String(p) !== String(props.projectId) || String(roomId) !== String(room.value?.id)) return; summary.value = sum.data; receivables.value = bills.data.rows || []; payments.value = receipts.data.rows || []; } finally { if (v === version) loading.value = false; } }
async function open(target: Partial<RoomVO>) { if (!target.id) return; room.value = target as RoomVO; visible.value = true; await refresh(); }
async function openPayment(row: Partial<PaymentVO>) { if (!row.id) return; const p = props.projectId, v = version; const res = await getPayment(row.id); if (v === version && String(p) === String(props.projectId)) { detail.value = res.data; detailVisible.value = true; } }
function openReverse(row?: any) { if (row) reverseDialog.value?.open(row as PaymentVO); }
async function handleReverseSuccess() { await refresh(); if (detailVisible.value && detail.value?.id) await openPayment(detail.value); }
function reset() { version++; room.value = undefined; receivables.value = []; payments.value = []; detail.value = undefined; detailVisible.value = false; }
watch(() => props.projectId, () => { visible.value = false; paymentDialog.value?.close(); reverseDialog.value?.close(); reset(); });
defineExpose({ open, close: () => { visible.value = false; paymentDialog.value?.close(); reverseDialog.value?.close(); } });
</script>

<style scoped>.ledger-label{color:var(--el-text-color-secondary)}.ledger-value{font-size:22px;font-weight:600;margin-top:8px}</style>
